import{z as n,x as B,o as t,c as i,q as d,j as A,D as E,d as r,s as l,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"RTO 与恢复","description":"","frontmatter":{"title":"RTO 与恢复","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/rto-recovery.md","filePath":"cs/rto-recovery.md","lastUpdated":1791063341000}'),p={name:"cs/rto-recovery.md"};function T(R,a,u,_,D,m){const o=B("Mermaid");return t(),i("div",null,[a[2]||(a[2]=d('<h1 id="rto-与恢复" tabindex="-1">RTO 与恢复 <a class="header-anchor" href="#rto-与恢复" aria-label="Permalink to &quot;RTO 与恢复&quot;">​</a></h1><div class="epigraph"><p>RTO 是允许的停机预算：分析+redo+undo+打开连接要落在预算内。检查点间隔、日志设备、并行 redo 是杠杆，不是口号。</p><footer>—— 据 Gray and Reuter 恢复时间；ARIES 三阶段；运维 RTO/RPO</footer></div><p><a href="/cs/durability-levels">上一课</a>钉了丢多少。本课钉<strong>多久能服务</strong>：恢复时间目标（RTO）。模糊检查点缩短 redo 前缀；并行 redo 缩短墙钟；undo 未决事务量也算。备份后课是另一条「从零拉起到某时间点」的 RTO。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>崩溃：启动三阶段。redo 体积 ≈ 检查点以来的日志 × 应用速度。脏页多、日志在慢盘、单线程 redo，RTO 爆炸。缺口是把恢复当性能路径设计：日志盘、redo 并行度、检查点节奏、崩溃时未决事务数（长事务 undo 长）。<span class="marginnote">直觉类比：检查点就像每天下班前把账本誊清一份——着火（崩溃）后只需补誊当天账目（redo），而不用从头补全部历史；账本誊得越勤，着火后要补的账越少，但白天誊账的时间（运行时开销）也越多。</span></p><p>演练：不演练的 RTO 是假的。与计划回归不同，这是运维不变式。</p><p><span class="marginnote">RTO 含故障检测、选主、DNS、连接池排空。本课核心是库进程恢复。检测与租约在分布式课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>预算分解：检测 \\(t_d\\) + 分析 \\(t_a\\) + redo \\(t_r\\) + undo \\(t_u\\) + 预热 \\(t_w\\)。杠杆：更频检查点降 \\(t_r\\)；限制长事务降 \\(t_u\\)；备库升主把 \\(t_r\\) 换成复制延迟（可能更短）。预热：缓冲池空则刚恢复仍慢，要预热或接受缓存冷。<span class="marginnote">数字实例：检查点每 10 分钟做一次，崩溃那一刻日志最多积压 10 分钟，redo 就要花约 10 分钟；把检查点间隔缩到 2 分钟，\\(t_r\\) 的上限立刻变成约 2 分钟——这是拿运行时的检查点开销，换恢复时间的硬上限。</span></p><p>监控：上次恢复各阶段耗时。日志积压告警等于 RTO 恶化预警。</p>',10)),(t(),A(s,null,{default:E(()=>[l(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20CRASH%5B%22%E5%B4%A9%E6%BA%83%22%5D%20--%3E%20DET%5B%22%E6%A3%80%E6%B5%8B%22%5D%0A%20%20DET%20--%3E%20REC%5B%22%E5%88%86%E6%9E%90%20redo%20undo%22%5D%0A%20%20REC%20--%3E%20OPEN%5B%22%E6%8E%A5%E5%8F%97%E8%BF%9E%E6%8E%A5%22%5D%0A%20%20OPEN%20--%3E%20WARM%5B%22%E7%BC%93%E5%86%B2%E9%A2%84%E7%83%AD%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"与组提交无关直接，但日志设备共享会让运行与恢复抢。doublewrite 恢复先修页，计入 \\(t_r\\)。逻辑重放备库的 RTO 是重放追上，不是 ARIES。",-1)),a[5]||(a[5]=e("p",null,[r("云盘快照恢复：RTO 含挂载与 WAL 追，粒度不同。"),e("span",{class:"marginnote"},"常见误区：初学者容易以为「进程起来、端口开始监听 = 恢复完成」——缓冲池全冷时每条查询都要现从磁盘拉页，「已恢复」的系统可能比停机还慢；预热必须计入 RTO 预算，否则用户看到的仍是超时。")],-1)),(t(),A(s,null,{default:E(()=>[l(o,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20BUD%5B%22%E9%97%AE%E9%A2%98%EF%BC%9ARTO%20%E9%A2%84%E7%AE%97%E6%80%8E%E4%B9%88%E5%8E%8B%22%5D%20--%3E%20TR%5B%22redo%20%E6%97%B6%E9%95%BF%20t_r%22%5D%0A%20%20BUD%20--%3E%20TU%5B%22undo%20%E6%97%B6%E9%95%BF%20t_u%22%5D%0A%20%20BUD%20--%3E%20TW%5B%22%E9%A2%84%E7%83%AD%E6%97%B6%E9%95%BF%20t_w%22%5D%0A%20%20TR%20--%3E%20L1%5B%22%E6%A3%80%E6%9F%A5%E7%82%B9%E6%9B%B4%E9%A2%91%EF%BC%9A%E5%BE%85%E9%87%8D%E6%94%BE%E6%97%A5%E5%BF%97%E5%89%8D%E7%BC%80%E5%8F%98%E7%9F%AD%22%5D%0A%20%20TR%20--%3E%20L2%5B%22redo%20%E5%B9%B6%E8%A1%8C%EF%BC%9A%E5%A2%99%E9%92%9F%E7%BA%A6%E7%AD%89%E4%BA%8E%E4%BD%93%E9%87%8F%E9%99%A4%E4%BB%A5%E5%B9%B6%E8%A1%8C%E5%BA%A6%22%5D%0A%20%20TU%20--%3E%20L3%5B%22%E9%99%90%E5%88%B6%E9%95%BF%E4%BA%8B%E5%8A%A1%EF%BC%9A%E5%B4%A9%E6%BA%83%E6%97%B6%E6%9C%AA%E5%86%B3%E4%BA%8B%E5%8A%A1%E5%8F%98%E5%B0%91%22%5D%0A%20%20TW%20--%3E%20L4%5B%22%E9%A2%84%E7%83%AD%E8%84%9A%E6%9C%AC%EF%BC%9A%E7%BC%93%E5%AD%98%E4%B8%8D%E5%85%A8%E5%86%B7%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=d('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 PITR 选时间点。也不把 RTO 当隔离级别。半同步影响的是故障时 RPO 与是否能立刻升主。</p><p>后课默认：RTO 可分解、可演练、用检查点与并行 redo 调。备份与 PITR：从备份基线+日志前滚到任意点。</p><p>没有预热的「已恢复」对用户仍是超时。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RTO 分解为检测与三阶段加预热。</li><li>检查点、并行 redo、限制长事务是杠杆。</li><li>备份与 PITR 下一课。</li><li>出处：Gray and Reuter；ARIES；RTO/RPO 实践。</li></ul>',6))])}const O=n(p,[["render",T]]);export{h as __pageData,O as default};
